uniform float2 amzp_center;
uniform float amzp_radiusPx;
uniform float amzp_featherPx;
uniform float amzp_invert;
uniform float amzp_blurRadius;
uniform float amzp_intensity;
uniform float amzp_blendMode;







    float2 normCenter(float2 c){
      if(c.x > 2.0 || c.y > 2.0){
        return c / screen.zw; 
      }
      return c;
    }

    float4 blur1D(int tex, float2 uv, float2 dirPx, float amzp_radiusPx){
      float sigma = max(amzp_radiusPx, 1e-4) / 2.14596602;
      const float PIc = 3.14159265;
      float3 incG; incG.x = 1.0/(sqrt(2.0*PIc)*max(sigma,1e-4)); incG.y = exp(-0.5/(sigma*sigma)); incG.z = incG.y*incG.y;
      float4 acc = amzTexture(tex, uv) * incG.x; float wsum = incG.x;
      for(float i=1.0;i<=128.0;i+=2.0){
        float o0=i, o1=i+1.0; incG.xy *= incG.yz; float w0=incG.x; incG.xy *= incG.yz; float w1=incG.x;
        float w = w0+w1; float off=(o0*w0 + o1*w1)/max(w,1e-6);
        float2 ofs = dirPx * off;
        acc += amzTexture(tex, uv - ofs) * w;
        acc += amzTexture(tex, uv + ofs) * w;
        wsum += 2.0*w;
        if(i>amzp_radiusPx) break;
      }
      return acc / max(wsum,1e-6);
    }

    float3 blend_screen(float3 a, float3 b){ return 1.0 - (1.0-a)*(1.0-b); }
    float3 blend_overlay(float3 base, float3 over){ return mix(2.0*base*over, 1.0 - 2.0*(1.0-base)*(1.0-over), step(0.5, base)); }

    void amzRender(){
      float2 uv = amzScreenNorm();
      float2 px = 1.0 / (screen.zw/1.0);

      if(amzPass==0){
        amzOutput = blur1D(0, uv, float2(px.x, 0.0), amzp_blurRadius);
        return;
      }
      if(amzPass==1){
        amzOutput = blur1D(1, uv, float2(0.0, px.y), amzp_blurRadius);
        return;
      }


      float4 src = amzTexture(0, uv);
      float3 blurRGB = amzTexture(2, uv).rgb;

      float2 cN = normCenter(amzp_center);

      float r = amzp_radiusPx / max(screen.zw.x, 1.0);
      float f = max(amzp_featherPx, 0.0) / max(screen.zw.x, 1.0);

      float dist = length(uv - cN);
      float edge0 = r - 0.5*f;
      float edge1 = r + 0.5*f;
      float mask = smoothstep(edge1, edge0, dist); 
      if((amzp_invert>0.5)){ mask = 1.0 - mask; }

      float k = clamp(amzp_intensity * mask, 0.0, 1.0);
      float3 mixed = mix(src.rgb, blurRGB, k);

      if(int(amzp_blendMode)==1){ mixed = blend_screen(src.rgb, mixed); }
      else if(int(amzp_blendMode)==2){ mixed = blend_overlay(src.rgb, mixed); }

      amzOutput = float4(mixed, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
